<?php
use App\Models\Branch;use App\Models\ProductionQualityInspection;use App\Models\ProductionQualityPlan;use App\Support\CompanyFeatures;use Livewire\WithPagination;use function Livewire\Volt\{layout,mount,state,uses};layout('layouts.app');uses([WithPagination::class]);state(['search'=>'','stageFilter'=>'','resultFilter'=>'','approvalFilter'=>'','branchFilter'=>'','dateFrom'=>'','dateTo'=>'']);mount(fn()=>abort_unless(CompanyFeatures::manufacturingEnabled()&&auth()->user()?->canAny(['production.view_quality','production.perform_quality_inspections','production.approve_quality']),403));?>
<div><x-page-header :title="__('production.quality.inspections')" description="Immutable quality results, approvals, failures, and retests." :breadcrumbs="['Dashboard'=>route('dashboard'),__('production.title')=>route('production.index'),__('production.quality.title')=>null]"/><div class="mb-4 flex flex-wrap gap-2"><a href="{{route('production.quality.plans.index')}}" wire:navigate class="rounded-lg border px-3 py-2 text-sm font-bold">Plans</a><a href="{{route('production.quality.holds.index')}}" wire:navigate class="rounded-lg border px-3 py-2 text-sm font-bold">Holds</a>@can('production.perform_quality_inspections')<a href="{{route('production.quality.inspections.create')}}" wire:navigate class="rounded-lg bg-build-orange px-3 py-2 text-sm font-black text-white">Create inspection</a>@endcan</div><x-card><div class="mb-4 grid gap-3 md:grid-cols-4 xl:grid-cols-7"><input wire:model.live.debounce.300ms="search" placeholder="Inspection, product, order, batch, machine…" class="rounded-lg border-slate-200 md:col-span-2 dark:bg-navy-950"><select wire:model.live="stageFilter" class="rounded-lg border-slate-200 dark:bg-navy-950"><option value="">All stages</option>@foreach(ProductionQualityPlan::STAGES as $v)<option value="{{$v}}">{{str($v)->headline()}}</option>@endforeach</select><select wire:model.live="resultFilter" class="rounded-lg border-slate-200 dark:bg-navy-950"><option value="">All results</option>@foreach(ProductionQualityInspection::RESULTS as $v)<option value="{{$v}}">{{str($v)->headline()}}</option>@endforeach</select><select wire:model.live="approvalFilter" class="rounded-lg border-slate-200 dark:bg-navy-950"><option value="">All approvals</option>@foreach(ProductionQualityInspection::APPROVALS as $v)<option value="{{$v}}">{{str($v)->headline()}}</option>@endforeach</select><select wire:model.live="branchFilter" class="rounded-lg border-slate-200 dark:bg-navy-950"><option value="">All branches</option>@foreach(Branch::orderBy('name')->get() as $b)<option value="{{$b->id}}">{{$b->name}}</option>@endforeach</select><input type="date" wire:model.live="dateFrom" class="rounded-lg border-slate-200 dark:bg-navy-950"><input type="date" wire:model.live="dateTo" class="rounded-lg border-slate-200 dark:bg-navy-950"></div>
@php($inspections=ProductionQualityInspection::query()->forCurrentCompany()->accessibleTo(auth()->user())->with(['product','productionOrder','curingBatch','machine','inspector','holds'=>fn($q)=>$q->active()])->when($search,fn($q)=>$q->where(fn($x)=>$x->where('inspection_number','like',"%{$search}%")->orWhereHas('product',fn($p)=>$p->where('name','like',"%{$search}%"))->orWhereHas('productionOrder',fn($o)=>$o->where('order_number','like',"%{$search}%"))->orWhereHas('curingBatch',fn($b)=>$b->where('batch_number','like',"%{$search}%"))->orWhereHas('machine',fn($m)=>$m->where('name','like',"%{$search}%"))))->when($stageFilter,fn($q)=>$q->where('inspection_stage',$stageFilter))->when($resultFilter,fn($q)=>$q->where('result',$resultFilter))->when($approvalFilter,fn($q)=>$q->where('approval_status',$approvalFilter))->when($branchFilter,fn($q)=>$q->where('branch_id',$branchFilter))->when($dateFrom,fn($q)=>$q->whereDate('inspected_at','>=',$dateFrom))->when($dateTo,fn($q)=>$q->whereDate('inspected_at','<=',$dateTo))->latest('inspected_at')->paginate(15))
<div class="overflow-x-auto"><x-table :headers="['Inspection','Product / Context','Stage','Date','Inspector','Result','Approval','Hold','Actions']">@forelse($inspections as $inspection)<tr><td class="px-3 py-3 font-black">{{$inspection->inspection_number}}</td><td class="px-3 py-3">{{$inspection->product?->name}}<br><span class="text-xs text-slate-500">{{$inspection->productionOrder?->order_number?:$inspection->curingBatch?->batch_number}}</span></td><td class="px-3 py-3">{{str($inspection->inspection_stage)->headline()}}</td><td class="px-3 py-3">{{$inspection->inspected_at->format('d M Y H:i')}}</td><td class="px-3 py-3">{{$inspection->inspector?->name}}</td><td class="px-3 py-3 font-bold">{{str($inspection->result)->headline()}}</td><td class="px-3 py-3">{{str($inspection->approval_status)->headline()}}</td><td class="px-3 py-3">{{$inspection->holds->isNotEmpty()?'Active':'—'}}</td><td class="px-3 py-3"><a href="{{route('production.quality.inspections.show',$inspection)}}" wire:navigate class="rounded border px-2 py-1 text-xs font-bold">View</a></td></tr>@empty<tr><td colspan="9" class="px-4 py-10 text-center text-slate-500">No inspections found.</td></tr>@endforelse</x-table></div><div class="mt-4">{{$inspections->links()}}</div></x-card></div>
